foreach([$member=>'member',$viewer=>'viewer'] as $id=>$role){$pdo->prepare('INSERT INTO tenant_users(tenant_id,user_id) VALUES (?,?)')->execute([$tenant,$id]);$pdo->prepare('INSERT INTO project_members(tenant_id,project_id,user_id,role) VALUES (?,?,?,?)')->execute([$tenant,$projectId,$id,$role]);}
