function noteRequest(string $path,?array $data=null):array{global $base,$cookie;$ctx=stream_context_create(['http'=>['method'=>$data===null?'GET':'POST','ignore_errors'=>true,'follow_location'=>0,'header'=>"Cookie: {$cookie}\r\nAccept: application/json\r\nContent-Type: application/x-www-form-urlencoded\r\n",'content'=>$data===null?'':http_build_query($data)]]);$body=file_get_contents($base.$path,false,$ctx);preg_match('/\s(\d{3})\s/',$http_response_header[0],$m);return[(int)$m[1],json_decode($body,true)];}
$personal=$notes->create($owner,"Ideia pessoal\n<script>alert('xss')</script>",null);$scoped=$notes->create($member,'PRIVADO-MEMBRO',$projectId);$ownProject=$notes->create($owner,'Ideia do projeto',$projectId);
