$task=$notes->convert($owner,$personal,$projectId,$column);$row=$pdo->query('SELECT * FROM tasks WHERE id='.$task)->fetch();check(str_contains($row['description'],'<script>')&&str_contains($row['description'],"\n"),'Texto completo preservado como texto');check($notes->page($owner,null)['total']===0,'Conversão remove nota');check((int)$pdo->query('SELECT user_id FROM task_assignees WHERE task_id='.$task)->fetchColumn()===$owner,'Tarefa atribuída ao autor');noteError(409,fn()=>$boards->mutate($owner,$projectId,$version,'task.create',['column_id'=>$column,'title'=>'Versão antiga']),'Conversão atualiza versão do quadro');
$concurrent=$notes->create($owner,'Conversão única',null);$jobs=[];for($i=0;$i<2;$i++)$jobs[]=proc_open([PHP_BINARY,__DIR__.'/notes-convert-child.php',(string)$owner,(string)$concurrent,(string)$projectId,(string)$column],[STDIN,STDOUT,STDERR],$pipes,dirname(__DIR__));foreach($jobs as $job)check(is_resource($job)&&proc_close($job)===0,'Conversão concorrente');
check((int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE project_id={$projectId} AND title='Conversão única'")->fetchColumn()===1,'Concorrência cria uma tarefa');
$done=$notes->create($owner,str_repeat('Texto longo ',300),null);$doneTask=$notes->convert($owner,$done,$projectId,$state['columns'][4]['id']);$doneRow=$pdo->query('SELECT title,description,completed_at FROM tasks WHERE id='.$doneTask)->fetch();check(mb_strlen($doneRow['title'])===200&&mb_strlen($doneRow['description'])>200&&$doneRow['completed_at']!==null,'Título limitado, descrição integral, coluna concluída');
$archived=newNotesProject($owner,'Arquivado');$archivedNote=$notes->create($owner,'Antes de arquivar',$archived);$archivedColumn=$boards->state($owner,$archived)['columns'][0]['id'];$projects->change($owner,$archived,'archive');noteError(409,fn()=>$notes->create($owner,'Após arquivar',$archived),'Arquivado não recebe nota');noteError(409,fn()=>$notes->convert($owner,$archivedNote,$archived,$archivedColumn),'Arquivado não converte');
$csrf=boardLogin($users['owner']['email']);$html=request('/projects/'.$projectId)[1];check(strpos($html,'id="pd-about-title"')<strpos($html,'id="brainstorm"')&&strpos($html,'id="brainstorm"')<strpos($html,'id="pd-manage-title"'),'Brainstorm entre sobre/gerenciar');check(!str_contains($html,'PRIVADO-MEMBRO'),'Projeto não revela nota do membro');
check(noteRequest('/notes',['body'=>'Sem token'])[0]===419,'CSRF criação');check(noteRequest('/notes',['_token'=>$csrf,'body'=>'Inbox HTTP','user_id'=>$outside,'tenant_id'=>999])[0]===200,'Identidade vem da sessão');
$nid=(int)$pdo->query("SELECT MAX(id) FROM quick_notes WHERE user_id={$owner} AND project_id IS NULL")->fetchColumn();check(noteRequest('/notes/'.$nid.'/delete',[])[0]===419,'CSRF exclusão');check(noteRequest('/notes/'.$nid.'/convert',['_token'=>$csrf,'project_id'=>$projectId,'column_id'=>$column])[0]===200,'Conversão HTTP');
$ownerOnly=$notes->create($owner,'SOMENTE-AUTOR',null);$csrf=boardLogin($users['member']['email']);check(noteRequest('/notes/'.$ownerOnly.'/delete',['_token'=>$csrf])[0]===404,'IDOR exclusão');check(noteRequest('/notes/'.$ownerOnly.'/convert',['_token'=>$csrf,'project_id'=>$projectId,'column_id'=>$column])[0]===404,'IDOR conversão');
$pdo->prepare('DELETE FROM project_members WHERE tenant_id=? AND project_id=? AND user_id=?')->execute([$tenant,$projectId,$member]);noteError(404,fn()=>$notes->page($member,$projectId),'Acesso revogado bloqueia leitura');noteError(404,fn()=>$notes->delete($member,$scoped),'Acesso revogado bloqueia mutação');
$csrf=boardLogin($users['owner']['email']);for($i=0;$i<22;$i++)$notes->create($owner,'Página '.$i,null);$paged=$notes->page($owner,null,2);check(count($paged['items'])===3&&$paged['pages']===2,'Paginação privada');check(request('/tasks?notes_page=2')[0]===200,'Página de tarefas renderiza notas');check(request('/notes/new')[0]===200,'Formulário sem JS');
$csrf=boardLogin($users['unverified']['email']);check(noteRequest('/notes/projects')[0]===403,'Verificação de e-mail');$cookie='';check(noteRequest('/notes/projects')[0]===401,'Autenticação');
